-- [AD 3.3] GAME 서버가 소유하는 캐릭터 인벤토리/장비 테이블. 확장 근거는 다중 행 트랜잭션 원자성이다 - characters 단일 행 갱신은 트랜잭션 없이도 원자적이라 그 계층을 증명하지 못한다. '장착 슬롯당 1개' 유일성은 DB 제약이 아니다 - MySQL 에 부분 유니크 인덱스가 없어 애플리케이션 코드와 트랜잭션으로 지키고, 중간 실패가 롤백의 관측 지점이 된다.
CREATE TABLE IF NOT EXISTS `character_items` (
  `server_id` SMALLINT UNSIGNED NOT NULL,
  `character_id` BIGINT UNSIGNED NOT NULL,
  `item_uid` BIGINT UNSIGNED NOT NULL,
  `item_id` INT UNSIGNED NOT NULL,
  `stack_count` SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  `equip_slot` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`server_id`, `character_id`, `item_uid`),
  KEY `idx_character_items_equip_slot` (`server_id`, `character_id`, `equip_slot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- [AD 6] GAME 서버가 소유하는 캐릭터 영속 테이블. PK는 (server_id, character_id) - 한 계정이 여러 서버에 여러 캐릭터를 가진다. account_uid 는 platform-auth 가 소유하는 계정 식별자의 참조값이며 이 레포가 계정을 재설계하지 않는다. pos_x/pos_y 는 공유 필드 1개의 그리드 좌표, level/exp 는 성장 축 1개 - 둘 다 데모 최소 집합[AD 3.3]이며 이 표를 그 이상 늘리지 않는다.
CREATE TABLE IF NOT EXISTS `characters` (
  `server_id` SMALLINT UNSIGNED NOT NULL,
  `character_id` BIGINT UNSIGNED NOT NULL,
  `account_uid` BIGINT UNSIGNED NOT NULL,
  `name` VARCHAR(32) NOT NULL,
  `pos_x` INT NOT NULL DEFAULT 0,
  `pos_y` INT NOT NULL DEFAULT 0,
  `level` SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  `exp` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL,
  `last_login_at` DATETIME NULL,
  PRIMARY KEY (`server_id`, `character_id`),
  KEY `idx_characters_account_uid` (`server_id`, `account_uid`),
  UNIQUE KEY `uq_characters_name` (`server_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
